const fs = require('node:fs');
const path = require('node:path');
const root = './work/main/claude-haiku-5-5/d94129873028';
const files = [];
for (const dir of ['src', 'test']) {
  for (const f of fs.readdirSync(path.join(root, dir))) {
    if (f.endsWith('.js')) files.push(path.join(root, dir, f));
  }
}
const summary = [];
for (const file of files) {
  const before = fs.readFileSync(file, 'utf8');
  let after = before.replace(/\bretryPolicy\b/g, 'backoffPolicy');
  if (file.includes(path.sep + 'src' + path.sep)) {
    after = after.replace(/\bmaxAttempts: 3\b/g, 'maxAttempts: 5');
  }
  if (after !== before) {
    fs.writeFileSync(file, after);
    summary.push(path.relative(root, file));
  }
}
const leftover = await $`grep -rn "retryPolicy\|maxAttempts: 3\b" ${root}/src ${root}/test`;
const tests = await $`cd ${root} && node --test 2>&1`;
return { changed: summary, leftover: leftover.stdout, testExit: tests.exitCode, testOutput: tests.stdout.slice(-3000) };

